cat > /tmp/opencode/test-dispatcher.js <<'EOF'
const { deliver } = require('/workspace/src/dispatcher.js');

function makeIo(behavior) {
  const calls = [];
  return {
    calls,
    async post(path, event, options) {
      calls.push({ path, event, options });
      const r = behavior(calls.length - 1);
      if (r instanceof Error) throw r;
      return r;
    },
  };
}

const ok = (s = 200) => ({ status: s });

(async () => {
  // 1. Success on first try, with X-Event-Id header.
  let io = makeIo(() => ok(200));
  let res = await deliver(io, { id: 'evt-1', message: 'hi' });
  console.log('1 success:', res.status, 'calls:', io.calls.length, 'header:', io.calls[0].options && io.calls[0].options.headers);

  // 2. Two 502s then success -> retried.
  io = makeIo((i) => (i < 2 ? ok(502) : ok(200)));
  res = await deliver(io, { id: 'evt-2' });
  console.log('2 502-retry:', res.status, 'calls:', io.calls.length);

  // 3. Thrown network error then success -> retried.
  io = makeIo((i) => (i < 1 ? new Error('ECONNRESET') : ok(200)));
  res = await deliver(io, { id: 'evt-3' });
  console.log('3 throw-retry:', res.status, 'calls:', io.calls.length);

  // 4. Always 502 -> throws after MAX_ATTEMPTS.
  io = makeIo(() => ok(502));
  let threw = null;
  try { await deliver(io, { id: 'evt-4' }); } catch (e) { threw = e; }
  console.log('4 give-up: threw=', threw && threw.status, 'calls:', io.calls.length);

  // 5. 400 -> not retried, returned immediately.
  io = makeIo(() => ok(400));
  res = await deliver(io, { id: 'evt-5' });
  console.log('5 400-no-retry:', res.status, 'calls:', io.calls.length);

  // 6. Event without id -> no header arg, still works.
  io = makeIo(() => ok(200));
  res = await deliver(io, { message: 'no id' });
  console.log('6 no-id:', res.status, 'calls:', io.calls.length, 'options:', io.calls[0].options);

  // 7. eventId field name variant.
  io = makeIo(() => ok(200));
  await deliver(io, { eventId: 42 });
  console.log('7 eventId:', io.calls[0].options.headers);

  // 8. Always throws -> throws last error after MAX_ATTEMPTS.
  io = makeIo(() => new Error('boom'));
  threw = null;
  try { await deliver(io, { id: 'x' }); } catch (e) { threw = e; }
  console.log('8 throw-all: threw=', threw && threw.message, 'calls:', io.calls.length);
})();
EOF
